        $realShift=$app->one('SELECT * FROM pos_shifts WHERE id=? AND tenant_id=? AND branch_id=? AND user_id=? FOR UPDATE',[$shift['shift_id'],$d['tenant_id'],$d['branch_id'],$uid]);if(!$realShift||$realShift['status']!=='open')throw new DomainException('El turno de esa venta ya está cerrado.');
        $cid=(int)($sale['customer']['id']??0);$customer=null;if($cid){foreach($snap['customers'] as $c)if((int)$c['id']===$cid)$customer=$c;if(!$customer)throw new DomainException('Cliente fuera del catálogo local.');}
        else{$name=mb_substr(trim((string)($sale['customer']['name']??'')),0,150);$phone=trim((string)($sale['customer']['phone']??''));if($name!==''&&$phone!=='')$customer=r2_new_customer($app,['id'=>$d['tenant_id']],$name,$phone,$current,'caja');else{$email='final-'.(int)$d['tenant_id'].'@registro.fisitaap.local';$customer=$app->one('SELECT id,name,phone FROM users WHERE email=? AND role="customer"',[$email]);if(!$customer){$app->exec('INSERT INTO users(name,email,phone,password_hash,role) VALUES("Consumidor final",?,"",?,"customer")',[$email,password_hash(bin2hex(random_bytes(32)),PASSWORD_BCRYPT)]);$customer=['id'=>(int)$app->db->lastInsertId(),'name'=>'Consumidor final'];$app->exec('INSERT IGNORE INTO tenant_customers(tenant_id,user_id) VALUES(?,?)',[$d['tenant_id'],$customer['id']]);}}}$cid=(int)$customer['id'];
        $number='L-'.$d['id'].'-'.substr(str_replace('-','',$uuid),0,16);$payKey=substr(hash('sha256',$d['id'].'|'.$uuid),0,32);
        $app->exec('INSERT INTO sales(tenant_id,branch_id,shift_id,customer_id,sale_number,sale_type,customer_name,payment_method,subtotal,tax_total,total,amount_paid,change_due,status,notes,created_by,payment_key,created_at) VALUES(?,?,?,?,?,"quick",?,?,?,?,?,?,?,"completed",?,?,?,?)',[$d['tenant_id'],$d['branch_id'],$shift['shift_id'],$cid,$number,$customer['name'],count($payments)>1?'Pago combinado':(array_key_first($payments)??'Efectivo'),$quote['net']/100,$quote['tax']/100,$quote['total']/100,$quote['total']/100,($cash-$cashApplied)/100,'Venta local · '.$register,$uid,$payKey,$dateText]);$saleId=(int)$app->db->lastInsertId();$app->exec('UPDATE sales SET discount_total=?,notes=? WHERE id=?',[$quote['discount']/100,'Venta local · '.$register.(empty($sale['note'])?'':' · '.mb_substr((string)$sale['note'],0,1000)),$saleId]);
        $app->exec('INSERT INTO pos_tickets(tenant_id,branch_id,customer_id,ticket_number,sale_type,status,subtotal,tax_total,total,paid_total,opened_by,open_key,created_at) VALUES(?,?,?, ?,"quick","paid",?,?,?,?,?,?,?)',[$d['tenant_id'],$d['branch_id'],$cid,$number,$quote['net']/100,$quote['tax']/100,$quote['total']/100,$quote['total']/100,$uid,$payKey,$dateText]);$ticket=(int)$app->db->lastInsertId();$app->exec('UPDATE pos_tickets SET discount_total=? WHERE id=?',[$quote['discount']/100,$ticket]);if(r3_active($app))$app->exec('UPDATE pos_tickets SET notes=? WHERE id=?',[mb_substr((string)($sale['note']??''),0,1000),$ticket]);
        foreach($quote['lines'] as $line){$p=$line['product'];if(!$app->one('SELECT id FROM products WHERE id=? AND tenant_id=?',[$p['id'],$d['tenant_id']]))throw new DomainException('Un producto fue eliminado del negocio.');$app->exec('INSERT INTO sale_items(sale_id,product_id,product_name,sku,quantity,unit_price,unit_cost,tax_rate,line_subtotal,line_tax) VALUES(?,?,?,?,?,?,?,?,?,?)',[$saleId,$p['id'],$p['name'],$p['sku'],$line['quantity']/1000,$line['quantity']?$line['net']/$line['quantity']*10:0,$p['cost'],$p['rate']/100,$line['net']/100,$line['tax']/100]);if(r3_active($app)){$itemId=(int)$app->db->lastInsertId();$options=[];foreach($p['groups'] as $g)foreach($g['options'] as $o)if(in_array($o['id'],$line['options'],true))$options[]=['id'=>$o['id'],'name'=>$o['name'],'group_name'=>$g['name'],'price_delta'=>$o['price']/100];$app->exec('UPDATE sale_items SET options_json=?,notes=? WHERE id=?',[json_encode($options,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$line['note'],$itemId]);}$now=$app->one('SELECT price,sale_price FROM products WHERE id=?',[$p['id']]);if(pos_cents_148($now['sale_price']??$now['price'])!==$p['price'])$conflicts[]='Precio local conservado: '.$p['name'];}
        $stock=$quote['stock'];ksort($stock,SORT_NUMERIC);foreach($stock as $pid=>$qty){if(!$app->one('SELECT id FROM products WHERE id=? AND tenant_id=?',[$pid,$d['tenant_id']]))throw new DomainException('Componente de inventario eliminado.');$app->exec('INSERT INTO product_inventory(tenant_id,branch_id,product_id,quantity) VALUES(?,?,?,0) ON DUPLICATE KEY UPDATE id=id',[$d['tenant_id'],$d['branch_id'],$pid]);$inv=$app->one('SELECT * FROM product_inventory WHERE tenant_id=? AND branch_id=? AND product_id=? FOR UPDATE',[$d['tenant_id'],$d['branch_id'],$pid]);$before=(float)$inv['quantity'];$after=round($before-$qty/1000,3);if($after<0)$conflicts[]='Revisar inventario negativo: producto '.$pid;$app->exec('UPDATE product_inventory SET quantity=? WHERE id=?',[$after,$inv['id']]);$app->exec('INSERT INTO inventory_movements(tenant_id,branch_id,product_id,movement_type,quantity,before_quantity,after_quantity,reference_type,reference_id,notes,user_id) VALUES(?,?,?,"local_sale",?,?,?,"local_sale",?,?,?)',[$d['tenant_id'],$d['branch_id'],$pid,-$qty/1000,$before,$after,$saleId,'Venta local '.$number,$uid]);}
        foreach($payments as $method=>$amount)$app->exec('INSERT INTO pos_payments(ticket_id,sale_id,customer_id,payment_method,amount,received_by) VALUES(?,?,?,?,?,?)',[$ticket,$saleId,$cid,$method,$amount/100,$uid]);
        $conflicts=array_values(array_unique($conflicts));$app->exec('INSERT INTO fisitaap_r2_synced_sales(device_id,operation_id,payload_hash,sale_id,register_name,conflicts,local_date) VALUES(?,?,?,?,?,?,?)',[$d['id'],$uuid,$hash,$saleId,$register,$conflicts?implode(' · ',$conflicts):null,$dateText]);r2_loyalty_sale($app,$saleId);audit($app,(int)$d['tenant_id'],$uid,'r2_local_sale','sale',$saleId);$app->db->commit();$acks[]=['id'=>$uuid,'sale_id'=>$saleId,'conflicts'=>$conflicts];
    }catch(Throwable $ex){if($app->db->inTransaction())$app->db->rollBack();$errors[]=['id'=>$uuid,'error'=>$ex instanceof PDOException?'La base de datos rechazó esta venta. Solicita revisión.':$ex->getMessage()];}}
    // Only close after every submitted sale is durable. Failed sales remain on the central PC.
    if(!$errors)foreach($shifts as $meta)if(!empty($meta['closed_at'])){
        $link=$app->one('SELECT * FROM fisitaap_r2_shift_links WHERE device_id=? AND shift_uuid=?',[$d['id'],(string)$meta['id']]);if(!$link)continue;$closing=(int)r2_number($meta['closing_cash']??0,0,99999999999);$closed=strtotime((string)$meta['closed_at']);if(!$closed)continue;$hash=hash('sha256',json_encode([$closing,$meta['closed_at']],JSON_THROW_ON_ERROR));if($link['close_hash']&&$link['close_hash']!==$hash){$errors[]=['id'=>'shift:'.$meta['id'],'error'=>'El cierre del turno cambió.'];continue;}
        $app->db->beginTransaction();try{$s=$app->one('SELECT * FROM pos_shifts WHERE id=? FOR UPDATE',[$link['shift_id']]);if($closed<strtotime($s['opened_at'])||$closed>time()+300)throw new DomainException('Fecha de cierre inválida.');$cash=(float)$app->one('SELECT COALESCE(SUM(p.amount),0) total FROM pos_payments p JOIN sales s ON s.id=p.sale_id WHERE s.shift_id=? AND s.status="completed" AND p.payment_method="Efectivo"',[$s['id']])['total'];$expected=(float)$s['opening_cash']+$cash;$app->exec('UPDATE pos_shifts SET status="closed",closed_at=?,closing_cash=?,expected_cash=?,difference_amount=? WHERE id=?',[date('Y-m-d H:i:s',$closed),$closing/100,$expected,$closing/100-$expected,$s['id']]);$app->exec('UPDATE fisitaap_r2_shift_links SET close_hash=? WHERE device_id=? AND shift_uuid=?',[$hash,$d['id'],$meta['id']]);$app->db->commit();$closedShifts[]=$meta['id'];}catch(Throwable $ex){if($app->db->inTransaction())$app->db->rollBack();$errors[]=['id'=>'shift:'.$meta['id'],'error'=>'No se pudo registrar el cierre.'];}
    }
    return ['acknowledged'=>$acks,'closed_shifts'=>$closedShifts,'errors'=>$errors];
}
function r2_desktop_api(App $app,string $action):never {
    if(!is_post())json_response(['ok'=>false,'error'=>'Usa POST.'],405);$raw=file_get_contents('php://input');if(strlen($raw)>2*1024*1024)json_response(['ok'=>false,'error'=>'El lote es demasiado grande.'],413);
    try{$data=json_decode($raw,true,128,JSON_THROW_ON_ERROR);if(!is_array($data))throw new DomainException('Solicitud inválida.');
        if($action==='pair'){
            if(!rate_limit_persistent($app,'device_pair',client_identity((string)($data['device_id']??'')),8,300))json_response(['ok'=>false,'error'=>'Espera antes de intentar otra conexión.'],429);
            $app->db->beginTransaction();$d=$app->one('SELECT * FROM fisitaap_r2_devices WHERE id=? AND is_active=1 AND pair_expires>NOW() FOR UPDATE',[(int)($data['device_id']??0)]);if(!$d||!$d['pair_hash']||!hash_equals($d['pair_hash'],hash('sha256',(string)($data['code']??''))))throw new DomainException('Código de conexión inválido o vencido.');$token=bin2hex(random_bytes(32));$app->exec('UPDATE fisitaap_r2_devices SET token_hash=?,pair_hash=NULL,pair_expires=NULL,last_sync=NOW() WHERE id=?',[hash('sha256',$token),$d['id']]);$snap=r2_snapshot($app,$d);$app->db->commit();json_response(['ok'=>true,'token'=>$token,'snapshot'=>$snap]);
        }
        $headers=function_exists('getallheaders')?array_change_key_case(getallheaders(),CASE_LOWER):[];$auth=(string)($_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??$headers['authorization']??'');$token=str_starts_with($auth,'Bearer ')?substr($auth,7):(string)($_SERVER['HTTP_X_FISITAAP_DEVICE']??'');if(!preg_match('/^[a-f0-9]{64}$/',$token))json_response(['ok'=>false,'error'=>'Equipo no autorizado.'],401);
        $d=$app->one('SELECT * FROM fisitaap_r2_devices WHERE token_hash=? AND is_active=1',[hash('sha256',$token)]);if(!$d)json_response(['ok'=>false,'error'=>'El equipo fue desactivado. Las ventas pendientes se conservan en Windows.'],401);
        $t=$app->one('SELECT * FROM tenants WHERE id=? AND is_active=1',[$d['tenant_id']]);if(!$t||!physical_store_v14($t)||!module_enabled_v12($app,$t,'pos'))json_response(['ok'=>false,'error'=>'POS no está activo para el negocio.'],403);
        if($action==='release') { primary179_release($app,$d);json_response(['ok'=>true]); }
        if($action==='snapshot'){$snap=r2_snapshot($app,$d);$app->exec('UPDATE fisitaap_r2_devices SET last_sync=NOW() WHERE id=?',[$d['id']]);json_response(['ok'=>true,'snapshot'=>$snap]);}
        if($action==='sync'){$result=r2_sync_sales($app,$d,$data);$app->exec('UPDATE fisitaap_r2_devices SET last_sync=NOW() WHERE id=?',[$d['id']]);json_response(['ok'=>true]+$result);}
        throw new DomainException('Acción no disponible.');
    }catch(Throwable $ex){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>$ex instanceof PDOException?'No se pudo guardar la operación.':$ex->getMessage()],422);}
